        repeat (`IDLE_EDGES) @(negedge ck);
        $display("SMOKE_FOLD idle %h", fold);
        report_act();
`ifdef SLICE_DRIVE
        slice_programme();
        repeat (`TAIL_EDGES) @(negedge ck);
        $display("SMOKE_FOLD programme %h", fold);
        report_act();
`endif
        if (errs == 0) $display("SMOKE_PASS qwk_slice_attn MUT=%0d edges %0d", MUT, cyc);
        else $display("SMOKE_FAIL qwk_slice_attn MUT=%0d errors %0d", MUT, errs);
        $finish;
    end
endmodule
